'use strict';
const $=s=>document.querySelector(s);
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL=u=>{try{let v=new URL(u);return ['https:','http:'].includes(v.protocol)?escapeHTML(u):'#';}catch{return '#';}};
let category='全部',selected=location.hash.slice(1)||BUILDERS[0].id;
const cats=['全部',...new Set(BUILDERS.map(p=>p.category))];
function renderCategories(){ $('#categories').innerHTML=cats.map(c=>`<button type="button" class="${c===category?'active':''}" aria-pressed="${c===category}" data-cat="${escapeHTML(c)}">${escapeHTML(c)}</button>`).join(''); }
function renderIndex(){const q=$('#search').value.trim().toLowerCase();let list=BUILDERS.filter(p=>(category==='全部'||p.category===category)&&JSON.stringify(p).toLowerCase().includes(q));$('#count').textContent=`${list.length} / ${BUILDERS.length}`;$('#empty').hidden=!!list.length;$('#people').innerHTML=list.map(p=>`<button class="person-button ${p.id===selected?'active':''}" data-id="${p.id}" ${p.id===selected?'aria-current="true"':''}><span class="num">${String(BUILDERS.indexOf(p)+1).padStart(2,'0')}</span><span><strong>${escapeHTML(p.name)}</strong><small>${escapeHTML(p.short)}</small></span></button>`).join('');}
function renderProfile(){const p=BUILDERS.find(p=>p.id===selected)||BUILDERS[0];selected=p.id;$('#profile').innerHTML=`<div class="profile-topline"><span class="eyebrow">THE BUILDER FILES</span><span>${escapeHTML(p.origin)} · ${escapeHTML(p.category)}</span></div><div class="profile-header"><div class="profile-number">FILE ${String(BUILDERS.indexOf(p)+1).padStart(2,'0')} / ${String(BUILDERS.length).padStart(2,'0')}</div><h2>${escapeHTML(p.name)}</h2><p class="role">${escapeHTML(p.role)}</p><div class="meta-tags">${p.tags.map(t=>`<span>${escapeHTML(t)}</span>`).join('')}</div><div class="profile-social"><a href="${safeURL(p.home)}" target="_blank" rel="noopener noreferrer">网站／作品</a><a href="${safeURL(p.x)}" target="_blank" rel="noopener noreferrer">X 账号</a></div></div><p class="lead">${escapeHTML(p.thesis)}</p><p class="summary">${escapeHTML(p.summary)}</p><div class="section-heading"><span class="eyebrow">01 / IDEAS</span><h3>${p.official?'官方内容主线':'主要观点'}</h3></div><div class="ideas">${p.ideas.map((i,n)=>`<article class="idea"><span class="idea-number">${String(n+1).padStart(2,'0')}</span><div><h4>${escapeHTML(i.title)}</h4><p>${escapeHTML(i.text)}</p><a class="source-ref" href="${safeURL(p.works[i.source||0].url)}" target="_blank" rel="noopener noreferrer">依据：${escapeHTML(p.works[i.source||0].title)}</a></div></article>`).join('')}</div><div class="section-heading"><span class="eyebrow">02 / READING</span><h3>代表内容</h3></div><div class="works">${p.works.map((w,n)=>`<article class="work"><div class="work-meta"><span class="work-type">${escapeHTML(w.type)}</span><span>${escapeHTML(w.date)}</span><span>${escapeHTML(w.author)}</span></div><h4><a href="${safeURL(w.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(w.title)}</a></h4><p>${escapeHTML(w.summary)}</p><p class="reading-reason"><b>为什么值得读</b>　${escapeHTML(w.why)}</p>${w.access?`<p class="access">${escapeHTML(w.access)}</p>`:''}${w.evidence?`<a class="source-ref" href="${safeURL(w.evidence)}" target="_blank" rel="noopener noreferrer">已读取的逐字稿／镜像依据</a>`:''}<a class="work-link" href="${safeURL(w.url)}" target="_blank" rel="noopener noreferrer">${w.type.includes('访谈')||w.type.includes('演讲')?'观看／收听原内容':'阅读原内容'}</a></article>`).join('')}</div><div class="reading-note"><b>阅读提示 · 编辑判断</b>${escapeHTML(p.note)}</div>`;document.title=`${p.name} · Builder Atlas`;renderIndex();}
$('#search').addEventListener('input',renderIndex);$('#categories').addEventListener('click',e=>{const b=e.target.closest('[data-cat]');if(b){category=b.dataset.cat;renderCategories();renderIndex();}});$('#people').addEventListener('click',e=>{const b=e.target.closest('[data-id]');if(!b)return;selected=b.dataset.id;history.replaceState(null,'',`#${selected}`);renderProfile();$('#sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');window.scrollTo({top:0,behavior:'smooth'});});$('#menu').addEventListener('click',()=>{let open=$('#sidebar').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(open));});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');}});window.addEventListener('hashchange',()=>{if(BUILDERS.some(p=>p.id===location.hash.slice(1))){selected=location.hash.slice(1);renderProfile();}});renderCategories();renderProfile();
